async handleMe(request) {
    if (!request.info || !request.info.sessionToken) {
      throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', request.config);
    }
    const token = request.info.sessionToken;
    // Query the session with master key to validate the session token,
    // but do NOT include 'user' to avoid leaking user data via master context
    const sessionData = await rest.find(
      request.config,
      Auth.master(request.config),
      '_Session',
      { sessionToken: token },
      {},
      request.info.clientSDK,
      request.info.context
    );

    if (
      !sessionData.results ||
      sessionData.results.length === 0 ||
      !sessionData.results[0].user
    ) {
      throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', request.config);
    }

    const primaryId = sessionData.results[0].user.objectId;
    // Re-fetch the user with the caller's auth context so that
    // protectedFields, CLP, and auth adapter afterFind apply correctly
    const userDetails = await rest.get(
      request.config,
      request.auth,
      '_User',
      primaryId,
      {},
      request.info.clientSDK,
      request.info.context
    );

    if (!userDetails.results || userDetails.results.length === 0) {
      throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', request.config);
    }

    const userObject = userDetails.results[0];
    // Send token back on the login, because SDKs expect that.
    userObject.sessionToken = token;
    // Remove hidden properties.
    UsersRouter.removeHiddenProperties(userObject);
    return { response: userObject };
  }

