function (type, options, handler) {
  const isTypeString = typeof type === 'string'

  if (!(isTypeString || type instanceof RegExp)) throw new FST_ERR_CTP_INVALID_TYPE()
  if (isTypeString && type.length === 0) throw new FST_ERR_CTP_EMPTY_TYPE()
  if (typeof handler !== 'function') throw new FST_ERR_CTP_INVALID_HANDLER()

  if (this.existingParser(type)) {
    throw new FST_ERR_CTP_ALREADY_PRESENT(type)
  }

  if (options.parseAs !== undefined) {
    if (options.parseAs !== 'string' && options.parseAs !== 'buffer') {
      throw new FST_ERR_CTP_INVALID_PARSE_TYPE(options.parseAs)
    }
  }

  const parserInstance = new Parser(
    options.parseAs === 'string',
    options.parseAs === 'buffer',
    options.bodyLimit,
    handler
  )

  let result;
  if (isTypeString && type === '*') {
    this.customParsers.set('', parserInstance);
  } else {
    if (isTypeString) {
      this.parserList.unshift(new ParserListItem(type));
    } else {
      this.parserRegExpList.unshift(type);
    }
    this.customParsers.set(String(type), parserInstance);
  }
}

