  if (!nuxt.options.dev) {
    return
  }

  let serverSocketHandle: net.Server | undefined
  const { socketPath: sPath, parentDir: pDir } = generateSocketPath()
  const { invalidates: invalidator, markInvalidate: markInv, markInvalidates: markInvAll } = useInvalidates()

  let cleanupDone = false
  async function cleanUpSocket () {
    if (cleanupDone) { return }
