function processVersion(versionString, isLoose) {
  if (versionString.length > MAX_LENGTH)
    return null;

  var regexToUse = isLoose ? re[LOOSE] : re[FULL];
  if (!regexToUse.test(versionString))
    return null;

  try {
    return new SemVer(versionString, isLoose);
  } catch (error) {
    return null;
  }
}

